/**
 * Canonical host filesystem access layer (`ctx.fs`) shared by in-house plugins.
 *
 * Going through `ctx.fs` instead of `node:fs` ensures:
 *   1. Path identity, containment and sandbox policy come from the host.
 *   2. `ctx.emit('fs/observed', ...)` records reads in the host's
 *      read-before-edit table so subsequent host `edit`/`write` calls succeed.
 *
 * THIS FILE IS THE SOURCE OF TRUTH. Copies in plugins are generated by
 * `tools/sync-shared-code.mjs` and must stay byte-identical.
 *
 * ASCII only: see the workspace AGENTS.md encoding rule.
 */

import { Buffer } from 'node:buffer'

/** Session workspace cwd for a call, or undefined for a non-agent caller. */
export function sessionCwd(exec) {
  return exec?.agent?.session?.header?.cwd
}

/**
 * Resolve a model-supplied path in the caller's workspace.
 * @param {object} ctx - plugin context holding `fs`.
 * @param {object} exec - tool execution context.
 * @param {string} requested - model-supplied path.
 * @returns {Promise<{target: object, displayPath: string, cwd: string|undefined}>}
 */
export async function resolvePath(ctx, exec, requested) {
  if (typeof requested !== 'string' || requested.trim() === '') {
    const error = new Error('path must be a non-empty string')
    error.code = 'INVALID_PATH'
    throw error
  }
  const cwd = sessionCwd(exec)
  const target = await ctx.fs.resolve(requested, {
    ...(cwd !== undefined ? { cwd } : {}),
    signal: exec?.signal,
  })
  return { target, displayPath: target.displayPath, cwd }
}

/**
 * Stat a resolved target, optionally requiring a regular file.
 * @param {object} ctx
 * @param {object} exec
 * @param {{target: object, displayPath: string}} resolved
 * @param {{requireFile?: boolean}} [options]
 * @returns {Promise<{type: string, size?: number, version: string}>}
 */
export async function statTarget(ctx, exec, resolved, { requireFile = true } = {}) {
  const info = await ctx.fs.stat(resolved.target, exec?.signal)
  if (info === undefined) {
    ctx.emit('fs/observed', resolved.target, { kind: 'absent' }, exec)
    const error = new Error(`cannot read "${resolved.displayPath}": not found`)
    error.code = 'FS_NOT_FOUND'
    throw error
  }
  if (requireFile && info.type !== 'file') {
    const error = new Error(`cannot read "${resolved.displayPath}": not a regular file (${info.type})`)
    error.code = 'FS_NOT_REGULAR_FILE'
    throw error
  }
  return info
}

/**
 * Read at most `maxBytes` from a resolved target.
 *
 * By default records `fs/observed` immediately and returns the Buffer. Pass
 * `{ deferObserve: true }` when callers validate decoding/ranges afterwards and
 * only want to record the observation once the read succeeds; in that mode it
 * returns `{ buffer, markObserved }`.
 *
 * @param {object} ctx
 * @param {object} exec
 * @param {{target: object, displayPath: string}} resolved
 * @param {{size?: number, version: string}} info
 * @param {number} maxBytes
 * @param {{deferObserve?: boolean}} [options]
 * @returns {Promise<Buffer | {buffer: Buffer, markObserved: () => void}>}
 */
export async function readBytes(ctx, exec, resolved, info, maxBytes, { deferObserve = false } = {}) {
  if (typeof info.size === 'number' && info.size > maxBytes) {
    const error = new Error(
      `cannot read "${resolved.displayPath}": ${info.size} bytes exceeds the ${maxBytes}-byte limit`,
    )
    error.code = 'FS_TOO_LARGE'
    throw error
  }
  const raw = await ctx.fs.readBytes(resolved.target, exec?.signal, maxBytes)
  const buffer = Buffer.isBuffer(raw) ? raw : Buffer.from(raw)
  let observed = false
  const markObserved = () => {
    if (observed) return
    observed = true
    ctx.emit('fs/observed', resolved.target, { kind: 'present', version: info.version }, exec)
  }
  if (deferObserve) return { buffer, markObserved }
  markObserved()
  return buffer
}

/**
 * Decode UTF-8 strictly across the full buffer; a BOM is stripped, NUL or
 * invalid UTF-8 bytes are an explicit error with code `FS_NOT_TEXT`.
 * @param {Buffer|Uint8Array} buffer
 * @param {string} displayPath
 * @returns {string}
 */
export function decodeUtf8(buffer, displayPath) {
  const bytes = Buffer.isBuffer(buffer) ? buffer : Buffer.from(buffer)
  if (bytes.includes(0)) {
    const error = new Error(
      `cannot read "${displayPath}": binary content (NUL byte found). `
        + 'Use a document reader or the host hex reader instead of a text read.',
    )
    error.code = 'FS_NOT_TEXT'
    throw error
  }
  try {
    return new TextDecoder('utf-8', { fatal: true, ignoreBOM: false }).decode(bytes)
  } catch {
    const error = new Error(
      `cannot read "${displayPath}": the file is not valid UTF-8. `
        + 'Open it with a document reader or the host hex view instead of lossy text replacement.',
    )
    error.code = 'FS_NOT_TEXT'
    throw error
  }
}
